import type { Conflict, Disruption, Minutes, Plan, PlanItem } from './types.ts';
import type { CascadeResult } from './types.ts';
import { conflictKey, simulateCascade } from './cascade.ts';
import type { Future, FuturesResult } from './futures.ts';
import { fmtClock } from './time.ts';
import type { Change, RescueStatus } from './rescue.ts';

/**
 * "pip explains why": plain-english sentences built only from numbers the engine computed.
 * nothing here is generated by a language model and nothing is invented: every sentence is a template whose blanks are filled
 * from a simulation result, and each line carries the numbers it used (`facts`) so they can be checked against the result.
 */

export type PipKind =
  | 'disruption'
  | 'buffer'
  | 'shortfall'
  | 'overlap'
  | 'fix'
  | 'change'
  | 'why_smallest'
  | 'kept'
  | 'deferred'
  | 'absorbed'
  | 'impossible'
  | 'cheapest_fix';

export interface PipLine {
  kind: PipKind;
  text: string;
  /** the numbers (minutes, counts) and names this sentence was built from */
  facts: Record<string, number | string>;
  itemIds: string[];
}

/** "45 minutes", "1 hour", "1 hour 15 minutes". */
export function pipWords(minutes: number): string {
  const m = Math.round(minutes);
  if (m < 60) return `${m} minute${m === 1 ? '' : 's'}`;
  const h = Math.floor(m / 60);
  const r = m % 60;
  const hs = `${h} hour${h === 1 ? '' : 's'}`;
  return r === 0 ? hs : `${hs} ${r} minute${r === 1 ? '' : 's'}`;
}

const BUFFER_LIMIT = 480;

export interface Buffer {
  /** the most minutes this one disruption could take, on its own, before something new breaks */
  minutes: number;
  /** true when nothing broke even at the search limit */
  atLimit: boolean;
  /** the first thing that breaks one minute later */
  wall: Conflict | null;
}

/**
 * how much room did the plan have for this disruption? exact (binary search over the cascade simulation, which is
 * monotone: a longer delay never removes a conflict). conflicts that already existed in the plan are ignored.
 */
export function bufferFor(plan: Plan, d: Extract<Disruption, { type: 'delay' | 'overrun' }>, limit = BUFFER_LIMIT): Buffer {
  const pre = new Set(simulateCascade(plan, []).conflicts.map(conflictKey));
  const probe = (m: number) => simulateCascade(plan, [{ ...d, minutes: m }]);
  const clean = (m: number) => probe(m).conflicts.every((c) => pre.has(conflictKey(c)));
  if (clean(limit)) return { minutes: limit, atLimit: true, wall: null };
  let lo = 0;
  let hi = limit;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (clean(mid)) lo = mid;
    else hi = mid;
  }
  const wall = probe(hi).conflicts.find((c) => !pre.has(conflictKey(c))) ?? null;
  return { minutes: lo, atLimit: false, wall };
}

function wallText(c: Conflict, plan: Plan, selfId?: string): string {
  const tz = plan.settings.timezone;
  const item = (id: string | undefined): PlanItem | undefined => plan.items.find((i) => i.id === id);
  const it = item(c.itemId);
  const other = item(c.otherId);
  const name = (x: PlanItem | undefined, fallback: string) => (x ? `"${x.title}"` : fallback);
  switch (c.code) {
    case 'deadline_missed':
      return `${c.itemId === selfId ? 'it' : name(it, 'a task')} misses its ${it?.deadline !== undefined ? `${fmtClock(it.deadline, tz)} ` : ''}deadline`;
    case 'locked_overlap':
      return `it collides with ${name(other, 'a locked commitment')}${other?.start !== undefined ? ` (locked, ${fmtClock(other.start, tz)})` : ''}`;
    case 'break_lost':
      return `${name(it, 'a protected break')} is pushed out of its window`;
    case 'overflow':
      return `${name(it, 'a task')} no longer fits before the day ends`;
    case 'after_hours':
      return `${name(it, 'a task')} runs outside your available hours`;
  }
}

export interface ExplainInput {
  plan: Plan;
  disruptions: readonly Disruption[];
  cascade: CascadeResult;
  futures: FuturesResult;
  repaired: Future | null;
  changes: readonly Change[];
  status: RescueStatus;
}

export function explainRescue(input: ExplainInput): PipLine[] {
  const { plan, disruptions, cascade, futures, repaired, changes, status } = input;
  const tz = plan.settings.timezone;
  const lines: PipLine[] = [];
  const title = (id: string) => plan.items.find((i) => i.id === id)?.title ?? id;
  const clock = (m: Minutes) => fmtClock(m, tz);

  /* ── what happened, and how much room there was ── */
  for (const d of disruptions) {
    if (d.type === 'delay' || d.type === 'overrun') {
      const what = title(d.targetId);
      const verb = d.type === 'overrun' ? `ran ${pipWords(d.minutes)} long` : `started ${pipWords(d.minutes)} late`;
      const b = bufferFor(plan, d);
      const short = Math.max(0, d.minutes - b.minutes);
      if (b.atLimit) {
        lines.push({ kind: 'buffer', text: `Your ${what} ${verb}, but the day had plenty of buffer: even ${pipWords(b.minutes)} would not break anything on its own.`, facts: { minutes: d.minutes, buffer: b.minutes }, itemIds: [d.targetId] });
      } else if (short === 0) {
        lines.push({ kind: 'buffer', text: `Your ${what} ${verb}, and you had ${pipWords(b.minutes)} of buffer before ${b.wall ? wallText(b.wall, plan, d.targetId) : 'anything broke'}, so this alone does not break the plan.`, facts: { minutes: d.minutes, buffer: b.minutes }, itemIds: [d.targetId] });
      } else {
        const room = b.minutes === 0 ? 'no buffer' : `only ${pipWords(b.minutes)} of buffer`;
        lines.push({
          kind: 'shortfall',
          text: `Your ${what} ${verb}, but you had ${room}${b.wall ? ` before ${wallText(b.wall, plan, d.targetId)}` : ''}. We need to find another ${pipWords(short)}.`,
          facts: { minutes: d.minutes, buffer: b.minutes, shortfall: short },
          itemIds: [d.targetId, ...(b.wall ? [b.wall.itemId] : [])],
        });
      }
    } else {
      const start = d.type === 'unexpected' ? d.start : d.start ?? Math.min(...plan.items.filter((i) => i.blocking && i.start !== undefined).map((i) => i.start!), plan.settings.horizon.start);
      const dur = d.type === 'unexpected' ? d.duration : d.minutes;
      const end = start + dur;
      const label = d.type === 'unexpected' ? `a ${pipWords(dur)} "${d.title?.trim() || 'Unexpected commitment'}"` : `${pipWords(dur)} of your day`;
      const hit = plan.items
        .filter((i) => i.blocking && i.start !== undefined)
        .map((i) => ({ i, o: Math.max(0, Math.min(end, i.start! + i.duration) - Math.max(start, i.start!)) }))
        .filter((x) => x.o > 0)
        .sort((a, b) => a.i.start! - b.i.start!);
      const taken = hit.reduce((s, x) => s + x.o, 0);
      const verb = d.type === 'unexpected' ? `landed at ${clock(start)}` : `disappeared starting at ${clock(start)}`;
      if (hit.length === 0) {
        lines.push({ kind: 'overlap', text: `${cap(label)} ${verb}, but that time was completely free, so nothing had to give way.`, facts: { minutes: dur, overlap: 0 }, itemIds: [] });
      } else {
        const who = hit.map((x) => `"${x.i.title}" (${pipWords(x.o)}${x.i.locked ? ', locked' : ''})`).join(', ');
        lines.push({ kind: 'overlap', text: `${cap(label)} ${verb}. ${pipWords(taken)} of that time was already taken by ${who}.`, facts: { minutes: dur, overlap: taken }, itemIds: hit.map((x) => x.i.id) });
      }
    }
  }

  if (disruptions.length > 1) {
    const n = cascade.conflicts.length;
    lines.push({
      kind: n ? 'shortfall' : 'absorbed',
      text: n ? `Together, if you changed nothing, that would cause ${n} conflict${n === 1 ? '' : 's'}.` : 'Together, if you changed nothing, nothing would break.',
      facts: { conflicts: n },
      itemIds: [],
    });
  }

  /* ── the answer ── */
  if (status === 'impossible') {
    const diag = futures.futures.find((f) => f.diagnosis)?.diagnosis;
    if (diag) {
      const [r, ...more] = diag.reasons;
      lines.push({ kind: 'impossible', text: r ? `No valid schedule exists. ${r.message}` : diag.summary, facts: { shortfall: r?.shortfallMinutes ?? 0 }, itemIds: diag.conflictSet });
      for (const m of more.slice(0, 2)) lines.push({ kind: 'impossible', text: m.message, facts: { shortfall: m.shortfallMinutes ?? 0 }, itemIds: m.itemIds });
      for (const s of diag.suggestions.slice(0, 2)) {
        lines.push({ kind: 'cheapest_fix', text: s.message, facts: { minutes: s.minutes ?? 0 }, itemIds: s.itemId ? [s.itemId] : [] });
      }
      lines.push({ kind: 'impossible', text: 'I changed nothing: your original schedule is untouched, and I will not break a lock, a deadline or a protected break to make the numbers work.', facts: {}, itemIds: [] });
    }
    return lines;
  }

  if (repaired) {
    const total = repaired.metrics.totalDisplacementMinutes;
    const moved = changes.length;
    if (status === 'absorbed' && moved === 0) {
      lines.push({ kind: 'absorbed', text: 'Nothing needs to move. The day absorbs this on its own.', facts: { moved: 0 }, itemIds: [] });
    } else {
      lines.push({
        kind: 'fix',
        text: `The smallest fix I found moves ${moved} ${moved === 1 ? 'item' : 'items'}, ${pipWords(total)} in total${repaired.deferred.length ? ` (and defers ${repaired.deferred.length})` : ''}.`,
        facts: { moved, totalMinutes: total, deferred: repaired.deferred.length },
        itemIds: changes.map((c) => c.id),
      });
      for (const c of changes) lines.push({ kind: 'change', text: c.why, facts: { delta: c.deltaMinutes }, itemIds: [c.id] });
    }
    for (const d of repaired.deferred) {
      lines.push({ kind: 'deferred', text: `${d.message} Nothing is removed without your say-so.`, facts: {}, itemIds: [d.id] });
    }

    // why this is the smallest: compare with the other strategies, using their computed metrics
    const others = futures.futures.filter((f) => f.strategy !== 'minimize_changes' && f.feasible);
    if (others.length && (moved > 0 || repaired.deferred.length > 0)) {
      const bits = others.map((f) => `${f.title} would move ${f.metrics.movedCount} (${pipWords(f.metrics.totalDisplacementMinutes)})${f.deferred.length ? ` and defer ${f.deferred.length}` : ''}`);
      lines.push({
        kind: 'why_smallest',
        text: `For comparison: ${bits.join('; ')}. I chose the option that defers nothing if it can, then touches the fewest items, then moves them the least.`,
        facts: { moved, totalMinutes: total },
        itemIds: [],
      });
    }

    // what stayed put
    const lockedOnes = plan.items.filter((i) => i.locked && i.blocking && i.kind !== 'break');
    if (lockedOnes.length) {
      lines.push({ kind: 'kept', text: `${listNames(lockedOnes.map((i) => `"${i.title}"`))} ${lockedOnes.length === 1 ? 'stays' : 'stay'} exactly where ${lockedOnes.length === 1 ? 'it is' : 'they are'} (locked).`, facts: { locked: lockedOnes.length }, itemIds: lockedOnes.map((i) => i.id) });
    }
    const breaks = repaired.items.filter((i) => i.kind === 'break' && !i.injected);
    for (const b of breaks) {
      const src = plan.items.find((i) => i.id === b.id);
      if (src && src.release !== undefined && src.deadline !== undefined) {
        lines.push({ kind: 'kept', text: `"${src.title}" is protected: it stays inside its ${clock(src.release)} to ${clock(src.deadline)} window (${clock(b.start)} to ${clock(b.end)}).`, facts: { start: b.start, end: b.end }, itemIds: [b.id] });
      }
    }
  }
  return lines;
}

function listNames(xs: string[]): string {
  if (xs.length <= 1) return xs.join('');
  return `${xs.slice(0, -1).join(', ')} and ${xs[xs.length - 1]}`;
}
function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
